## Collapse all pups within litter
collapse_litter <- function(yall, targets) {
  counts <- yall$counts
  litters <- unique(targets$litter)
  counts_litter <- matrix(
    0,
    nrow = nrow(counts),
    ncol = 2 * length(litters),
    dimnames = list(
      rownames(counts),
      NULL
    )
  )
  colnames_litter <- character(2 * length(litters))
  j <- 1
  for (L in litters) {
    ## Identify all libraries belonging to this litter
    samples <- targets$sample[
      targets$litter == L
    ]
    ## Choose a representative litter-level sample name e.g. Ctrl_2
    sample_name <- samples[1]
    ## Identify methylated/unmethylated columns
    me_cols <- paste0(samples, "-Me")
    un_cols <- paste0(samples, "-Un")
    
    ## Sum pups belonging to the same litter
    counts_litter[, j] <-
      rowSums(
        counts[, me_cols, drop = FALSE]
      )
    counts_litter[, j + 1] <-
      rowSums(
        counts[, un_cols, drop = FALSE]
      )
    ## Litter-level display name
    colnames_litter[j] <-
      paste0(sample_name, "-Me")
    colnames_litter[j + 1] <-
      paste0(sample_name, "-Un")
    j <- j + 2
  }
  colnames(counts_litter) <- colnames_litter
  counts_litter
}

