## Methods 2: EDA using PCA for uncorrected beta values #########
data_mat_clean <- beta_data_clean[ apply(beta_data_clean, 1, function(x) all(is.finite(x))), ]
data_mat_clean <- data_mat_clean[ apply(data_mat_clean, 1, sd) > 0, ]
pca_res <- prcomp(t(data_mat_clean),center = T, scale. = T)

## Extract PCA results
