##**PART 4: CpG enrichment relative to the CpG RRBS reference********###
#======================================================================#
final_annotated$gene_feature <- sub(" \\(.*", "", final_annotated$annotation)
final_annotated$cpg_feature <- final_annotated$CpG_context
final_annotated$cpg_feature[final_annotated$cpg_feature == "others"] <- "inter"
head(final_annotated)

## Reference CpG annotation table (same columns)
## mspl_ref, it's an excel file containing pre-filtered RRBS targeted loci
ref_anno <- read.xlsx(mspl_ref)
ref_anno$gene_feature <- sub(" \\(.*", "", ref_anno$annotation)
ref_anno$cpg_feature <- ref_anno$annot.type
head(ref_anno)

## Function to calculate DMP enrichment relative to the RRBS target
enrich_test <- function(dmp_df, ref_df, feature_col) {
  dmp_counts <- dmp_df %>%
    dplyr::count(!!sym(feature_col), name = "dmp_count")
  ref_counts <- ref_df %>%
    dplyr::count(!!sym(feature_col), name = "ref_count")
  
  counts <- full_join(dmp_counts, ref_counts, by = feature_col) %>%
    replace(is.na(.), 0)
  
  total_dmp <- sum(counts$dmp_count)
  total_ref <- sum(counts$ref_count)
  
  results <- counts %>%
    rowwise() %>%
    mutate(
      fisher_p = fisher.test(
        matrix(c(
          dmp_count, total_dmp - dmp_count,
          ref_count, total_ref - ref_count
        ), nrow = 2)
      )$p.value,
      enrichment = (dmp_count / total_dmp) / (ref_count / total_ref),
      log2_enrichment = log2(enrichment)
    ) %>%
    ungroup() %>%
    mutate(fdr = p.adjust(fisher_p, method = "BH")) %>%
    arrange(desc(enrichment))
  
  return(results)
}

## Run DMP enrichment for the gene features (promoter, intron...)
gene_enrichment <- enrich_test(final_annotated, ref_anno, "gene_feature")
head(gene_enrichment)

## Run DMP enrichment for the CpG features (island, shore, shelf and inter)
cpg_enrichment <- enrich_test(final_annotated, ref_anno, "cpg_feature")
head(cpg_enrichment)

### Save results
write_xlsx(gene_enrichment, paste0(target_sheet, "_DMP_GeneFeature_Enrichment.xlsx"))
write_xlsx(cpg_enrichment, paste0(target_sheet, "_DMP_CpGFeature_Enrichment.xlsx"))

## Plot the gene feature enrichment
gene_plot <- ggplot(gene_enrichment, aes(x = reorder(gene_feature, log2_enrichment),
                                         y = log2_enrichment, fill = -log10(fdr))) +
  geom_bar(stat = "identity") +
  coord_flip() +
  geom_hline(yintercept = 0, linetype = "dashed") +
  scale_fill_gradient(low = "skyblue", high = "darkred") +
  labs(
    x = "Gene Feature",
    y = "log2(Enrichment ratio)",
    fill = "-log10(FDR)",
    title = paste0(sex, " ", chem, ": DMP Enrichment in Gene Features")
  ) +
  theme_bw(base_size = 12)
